import {useEffect,useMemo,useRef,useState} from "react";
import logo from "../../assets/logo.png";
import widget from "../../assets/widget.png";

type TabKey="analysis"|"results"|"references_new"|"export";
type Specimen={id:string;imageCount:number;analysisImageCount:number;identificationImageCount:number;hasResult:boolean;runCount:number};
type Project={name:string;path:string;specimens:Specimen[]};
type ImageItem={name:string;src:string;analysisSelected:boolean;analysisEligible:boolean;isIdentification:boolean};
type RunSummary={runId:string;specimenId:string;createdAt:string;provider:string;model:string;status:string;primaryCode:string;primaryConfidence?:number;secondaryCodes:string[];detectedCodes:string[];featureCount:number;durationSeconds?:number;legacy:boolean;evaluationVariant?:string;seriesId?:string;seriesName?:string;resultGroup:"historical"|"scientific";hidden:boolean;hiddenAt?:string;visibleObservations?:string[];assessment?:any};
type Detail={specimen:string;images:ImageItem[];result:any;correction:any;resultPath?:string;history:RunSummary[]};
type ModelKey="qwen"|"openai"|"mistral";
type BatchJob={jobId:string;runId:string;specimen:string;provider:string;model:string;status:string;stage:string;statusText?:string;error?:string;resultPath?:string;selectedImages?:string[];startedAt?:string;finishedAt?:string};
type Batch={batchId:string;status:string;jobCount:number;cloudRequestCount:number;jobs:BatchJob[];createdAt?:string;dismissedJobCount?:number};

const modelChoices:Record<ModelKey,{provider:string;model:string;label:string;cloud:boolean}>={
 qwen:{provider:"ollama",model:"qwen3-vl:4b-instruct",label:"Qwen3-VL 4B Instruct · lokal",cloud:false},
 openai:{provider:"openai",model:"gpt-6.1-sol",label:"OpenAI GPT-6.1 · Cloud",cloud:true},
 mistral:{provider:"mistral",model:"ministral-3b-2512",label:"Mistral Ministral 3B · Cloud",cloud:true},
};
const evaluationVariantLabels:Record<string,string>={
 "1":"Ohne Referenzbilder",
 "2":"Kleine Referenzdatenbank",
 "2a":"Erweiterte Referenzdatenbank",
 "3":"Annotierte Referenzbilder mit Bildbeschreibungen",
};
const evaluationVariantDescriptions:Record<string,string>={
 "1":"Die Analyse verwendet nur die ausgewählten Prüfkörperbilder und die Klassifikationsregeln. Es werden keine Referenzbilder übertragen.",
 "2":"Die Analyse verwendet den kleinen, festgelegten Referenzbildbestand der Variante 2.",
 "2a":"Die Analyse verwendet den erweiterten Referenzbildbestand der Variante 2a.",
 "3":"Die Analyse verwendet die Bilder aus Variante 2a zusammen mit den fachlich geprüften Bildbeschreibungen aus Variante 3.",
};
const tabs:[TabKey,string][]=[["analysis","Bildanalyse"],["results","Ergebnisse"],["references_new","Referenzdatenbank"],["export","Export"]];
const api=async(name:string,payload?:any)=>{const fn=window.pywebview?.api?.[name];if(!fn)throw new Error("Python-Bridge ist noch nicht bereit.");return fn(payload)};
const statusLabels:Record<string,string>={queued:"Wartend",running:"Läuft",succeeded:"Erfolgreich",partially_succeeded:"Teilweise erfolgreich",failed:"Fehlgeschlagen",paused:"Pausiert",cancelled:"Abgebrochen",interrupted:"Unterbrochen"};
const removableBatchStatuses=new Set(["succeeded","failed","cancelled"]);
const elapsedLabel=(startedAt:string|undefined,finishedAt:string|undefined,now:number)=>{if(!startedAt)return "–";const started=Date.parse(startedAt);const ended=finishedAt?Date.parse(finishedAt):now;if(!Number.isFinite(started)||!Number.isFinite(ended))return "–";const seconds=Math.max(0,Math.floor((ended-started)/1000));return `${Math.floor(seconds/60)} min ${String(seconds%60).padStart(2,"0")} s`};
const dateLabel=(value:string)=>value?new Date(value).toLocaleString("de-AT"):"Historischer Lauf";
const evidenceLabel=(value:string|undefined)=>value==="sicher_sichtbar"?"Sicher sichtbar":value==="vermutet"?"Vermutet":"Evidenzstatus nicht dokumentiert";
const initialAssessment=(item:any)=>{const saved=item.assessment?.schemaVersion==="2.0"?item.assessment:undefined;const features=item.displayFeatures||[];const manual=saved?.manualPrimaryFailure||saved?.expertPrimaryCause;return {featureReviews:saved?.featureReviews||features.map((feature:any)=>({reviewId:`review-${feature.feature_id}`,sourceFeatureId:feature.feature_id,status:"unreviewed",originalCode:feature.code,code:feature.code,visibleDescription:feature.visible_description||"",note:""})),expertPrimaryCode:manual?.code||"",reviewedBy:manual?.selectedBy||"",primaryRationale:saved?.expertPrimaryCause?.rationale||""}};

function RunCard({item,classes,draft,onDraft,onSave}:{item:any;classes:any[];draft:any;onDraft:(patch:any)=>void;onSave:()=>void}){
 const document=item.result||{};const result=document.result||{};const features=item.displayFeatures||result.class_suggestions||result.detected_features||[];const execution=document.execution||{};
 const reviews=draft?.featureReviews||[];const patchReview=(index:number,patch:any)=>onDraft({featureReviews:reviews.map((entry:any,i:number)=>i===index?{...entry,...patch}:entry)});const addFeature=()=>onDraft({featureReviews:[...reviews,{reviewId:`added-${Date.now()}`,sourceFeatureId:null,status:"added",originalCode:null,code:classes[0]?.code||"",visibleDescription:"",note:""}]});
 return <article className="recognized-result-card">
  <header><div><small>{document.specimen_id||document.analysis_id||item.specimen||"Prüfkörper"}</small><span>{execution.model||"Unbekanntes Modell"}</span></div><time>{dateLabel(document.created_at)}</time></header>
  <section><h3>Erkannte Merkmale</h3>{features.length?<ul className="recognized-class-list">{features.map((feature:any,index:number)=><li key={feature.feature_id||feature.suggestion_id||feature.code||index}><b>{feature.code}</b><span>{feature.name||"Bezeichnung nicht dokumentiert"}</span><small>{feature.confidence_label||"Konfidenz nicht dokumentiert"}</small><em className={`evidence-status ${feature.evidence_status||"nicht-dokumentiert"}`}>{evidenceLabel(feature.evidence_status)}</em></li>)}</ul>:<p className="no-recognized-features">{result.analysis_outcome==="fachlich_unklar"?"Fachlich unklar.":result.analysis_outcome==="keine_merkmale_erkennbar"?"Keine Merkmale erkennbar.":"Keine eindeutigen Merkmale erkannt."}</p>}</section>
  <details className="expert-review"><summary>Fachliche Bewertung</summary><section className="assessment"><p className="separation-note">Separat gespeichert; die ursprüngliche KI-Ausgabe bleibt unverändert.</p>{reviews.map((review:any,index:number)=><div className="feature-review" key={review.reviewId}><select value={review.status} onChange={event=>patchReview(index,{status:event.target.value})}><option value="unreviewed">Noch nicht geprüft</option><option value="confirmed">Bestätigt</option><option value="rejected">Verworfen</option><option value="corrected">Merkmal korrigiert</option>{review.sourceFeatureId==null&&<option value="added">Fehlendes Merkmal ergänzt</option>}</select><select value={review.code||""} disabled={review.status==="rejected"} onChange={event=>patchReview(index,{code:event.target.value,status:review.sourceFeatureId==null?"added":event.target.value===review.originalCode?review.status:"corrected"})}>{classes.map((entry:any)=><option value={entry.code} key={entry.code}>{entry.code} · {entry.name}</option>)}</select><input placeholder="Sichtbare Beschreibung / Lage" value={review.visibleDescription||""} onChange={event=>patchReview(index,{visibleDescription:event.target.value})}/><input placeholder="Optionale Prüfanmerkung" value={review.note||""} onChange={event=>patchReview(index,{note:event.target.value})}/></div>)}<button onClick={addFeature}>Fehlendes Merkmal hinzufügen</button><label>Primärversagen manuell auswählen<select value={draft?.expertPrimaryCode||""} onChange={event=>onDraft({expertPrimaryCode:event.target.value})}><option value="">Nicht festgelegt</option>{classes.map((entry:any)=><option value={entry.code} key={entry.code}>{entry.code} · {entry.name}</option>)}</select></label><label>Bewertende Person<input placeholder="Name" value={draft?.reviewedBy||""} onChange={event=>onDraft({reviewedBy:event.target.value})}/></label><textarea placeholder="Optionale fachliche Begründung" value={draft?.primaryRationale||""} onChange={event=>onDraft({primaryRationale:event.target.value})}/><button className="primary" onClick={onSave}>Fachliche Prüfung speichern</button></section></details>
 </article>;
}

function ReferenceDatabase({data,onData,onError,onStatus}:{data:any;onData:(value:any)=>void;onError:(value:string)=>void;onStatus:(value:string)=>void}){
 const [query,setQuery]=useState("");const [positions,setPositions]=useState<Record<string,number>>({});const [preview,setPreview]=useState<any>();
 const requirementLabel=(value:any)=>`Min. ${value?.minimum??"–"} · Ziel ${value?.target==null?"noch nicht festgelegt":value.target} · Max. ${value?.maximum==null?"offen":value.maximum}`;
 const filtered=(data?.classes||[]).filter((entry:any)=>`${entry.code} ${entry.name} ${entry.definition}`.toLocaleLowerCase("de").includes(query.toLocaleLowerCase("de")));
 const checkChanges=async()=>{const response=await api("refresh_evaluation_reference_database",{confirmManifestUpdate:false});if(!response?.ok){onError(response?.error||"Referenzdatenbank konnte nicht geprüft werden.");return}onData(response.catalog);onStatus(response.update.hasChanges?`${response.update.newCount} neue und ${response.update.missingCount} fehlende Dateien erkannt; noch nichts gespeichert.`:"Keine Manifeständerung erforderlich.")};
 const openFolder=async(code:string,variant:string)=>{const response=await api("open_evaluation_reference_folder",{code,variant});if(!response?.ok)onError(response?.error||"Ordner konnte nicht geöffnet werden.");else onStatus(`Ordner für ${code}, Variante ${variant}, im Finder geöffnet.`)};
 const editDescriptions=async()=>{const response=await api("open_variant3_descriptions");if(!response?.ok)onError(response?.error||"Beschreibungsdatei konnte nicht geöffnet werden.");else onStatus("descriptions.csv für die manuell geprüften Annotationstexte geöffnet.")};
 const refresh=async()=>{const first=await api("refresh_evaluation_reference_database",{confirmManifestUpdate:false});if(!first?.ok){onError(first?.error||"Referenzdatenbank konnte nicht geprüft werden.");return}const update=first.update;if(update.hasChanges){const duplicates=Object.values(update.variants||{}).reduce((sum:number,item:any)=>sum+(item.duplicateHashes?.length||0),0);const approved=confirm(`Ordnerprüfung abgeschlossen:\n\n${update.newCount} neue Bilder\n${update.missingCount} fehlende Bilder\n${duplicates} SHA-256-Duplikate\n\nVariantenmanifeste jetzt atomar aktualisieren? Originalbilder bleiben unverändert.`);if(!approved){onData(first.catalog);onStatus("Ordner neu eingelesen; Manifeständerung nicht bestätigt und daher nicht gespeichert.");return}const saved=await api("refresh_evaluation_reference_database",{confirmManifestUpdate:true});if(!saved?.ok){onError(saved?.error||"Manifest konnte nicht aktualisiert werden.");return}onData(saved.catalog);onStatus(`Referenzdatenbank aktualisiert: ${saved.update.updatedVariants?.join(", ")||"keine Manifeständerung"}.`);return}onData(first.catalog);onStatus("Referenzdatenbank geprüft; keine Manifeständerung erforderlich.")};
 const gallery=(entry:any,variant:string,images:any[])=>{const key=`${entry.code}-${variant}`;const index=Math.min(positions[key]||0,Math.max(0,images.length-1));const image=images[index];return <section className="variant-gallery"><header><div><b>Variante {variant}</b><small>{images.length} Bilder</small></div><div><button disabled={!images.length} onClick={()=>setPositions(current=>({...current,[key]:(index-1+images.length)%images.length}))}>‹</button><span>{images.length?`${index+1} / ${images.length}`:"0 / 0"}</span><button disabled={!images.length} onClick={()=>setPositions(current=>({...current,[key]:(index+1)%images.length}))}>›</button></div></header>{image?<>{variant==="3"?<div className="annotation-pair">{image.sourceImage?<button onClick={()=>setPreview(image.sourceImage)}><small>Original aus 2a</small><img src={image.sourceImage.src}/></button>:<div><small>Original aus 2a</small><span>Quellbild fehlt</span></div>}<button onClick={()=>setPreview(image)}><small>Annotierte Version aus 3</small><img src={image.src}/></button></div>:<button className="variant-image" onClick={()=>setPreview(image)}><img src={image.src}/><span>Vergrößern</span></button>}<dl><dt>Dateiname</dt><dd>{image.name}</dd><dt>Referenz-ID</dt><dd>{image.reference_id}</dd>{variant==="3"&&<><dt>source_reference_id</dt><dd>{image.source_reference_id||"Fehlt"}</dd></>}<dt>SHA-256</dt><dd>{image.sha256}</dd><dt>Fachlich bestätigt</dt><dd>{image.confirmed?"Ja":"Nein"}</dd><dt>Beschreibung</dt><dd>{image.description||"Keine Beschreibung hinterlegt"}</dd>{image.duplicateOf&&<><dt>Duplikat</dt><dd>{image.duplicateOf}</dd></>}</dl></>:<p className="empty-result">Noch keine Referenzbilder vorhanden.</p>}</section>};
 return <main className="tab-page"><div className="page-title"><div><h2>Referenzdatenbank</h2><p>Zwölf gleichwertige Referenzmerkmale · Varianten 2, 2a und 3</p></div><input placeholder="Merkmal suchen" value={query} onChange={event=>setQuery(event.target.value)}/><button onClick={editDescriptions}>V3-Beschreibungen bearbeiten</button><button onClick={checkChanges}>Änderungen prüfen</button><button className="primary" onClick={refresh}>Referenzdatenbank aktualisieren</button></div><div className="reference-toolbar"><span>{data?.note}</span><b>Variante 1 verwendet keine Referenzbilder.</b></div>{data?.refreshPreview?.hasChanges&&<div className="reference-update-note"><b>Ungespeicherte Ordneränderungen erkannt</b><span>{data.refreshPreview.newCount} neu · {data.refreshPreview.missingCount} fehlend</span></div>}<div className="evaluation-reference-grid">{filtered.map((entry:any)=><article className="evaluation-reference-card" key={entry.code}><header><div><b>{entry.code} · {entry.name}</b>{entry.reviewRequired&&<span className="incomplete">Fachlich zu prüfen</span>}<p>{entry.definition}</p></div><div><span className={entry.readiness?.["2"]?"complete":"incomplete"}>V2: {entry.countVariant2} · {requirementLabel(entry.requirements?.["2"])} · {entry.readiness?.["2"]?"BEREIT":"NICHT BEREIT"}</span><span className={entry.readiness?.["2a"]?"complete":"incomplete"}>V2a: {entry.countVariant2a} · {requirementLabel(entry.requirements?.["2a"])} · {entry.readiness?.["2a"]?"BEREIT":"NICHT BEREIT"}</span><span className={entry.readiness?.["3"]?"complete":"incomplete"}>V3 annotiert: {entry.countVariant3} · {requirementLabel(entry.requirements?.["3"])} · {entry.readiness?.["3"]?"BEREIT":"NICHT BEREIT"}</span><span className={entry.variant3DescriptionStatus.complete?"complete":"incomplete"}>V3-Texte: {!entry.variant3DescriptionStatus.totalCount?"keine Annotationen":entry.variant3DescriptionStatus.complete?"vollständig":`${entry.variant3DescriptionStatus.missingCount} fehlen`}</span><span className={entry.variant3SourceStatus.complete?"complete":"incomplete"}>Quellen: {entry.variant3SourceStatus.complete?"vollständig":"unvollständig"}</span><span className={entry.ready?"complete":"incomplete"}>Gesamt: {entry.ready?"BEREIT":"NICHT BEREIT"}</span></div></header><details><summary>Referenzbilder hinzufügen oder ersetzen</summary><p>Bilder werden bewusst im Finder in den jeweiligen Merkmalsordner gelegt. Anschließend „Änderungen prüfen“ und die Manifestaktualisierung bestätigen.</p><div><code>{entry.folderVariant2}</code><button onClick={()=>void openFolder(entry.code,"2")}>Variante 2 öffnen</button></div><div><code>{entry.folderVariant2a}</code><button onClick={()=>void openFolder(entry.code,"2a")}>Variante 2a öffnen</button></div><div><code>{entry.folderVariant3}</code><button onClick={()=>void openFolder(entry.code,"3")}>Variante 3 öffnen</button></div></details><div className="variant-galleries">{gallery(entry,"2",entry.imagesVariant2)}{gallery(entry,"2a",entry.imagesVariant2a)}{gallery(entry,"3",entry.imagesVariant3)}</div></article>)}</div>{preview&&<div className="lightbox reference-lightbox" onClick={()=>setPreview(undefined)}><div><img src={preview.src}/><p>{preview.name} · {preview.reference_id}</p></div></div>}</main>;
}

export default function App(){
 const [boot,setBoot]=useState<any>();const [project,setProject]=useState<Project>();const [tab,setTab]=useState<TabKey>("analysis");
 const [selected,setSelected]=useState("");const [detail,setDetail]=useState<Detail>();const [checkedSpecimens,setCheckedSpecimens]=useState<string[]>([]);const [selectedModels,setSelectedModels]=useState<ModelKey[]>(["qwen"]);const [singleModel,setSingleModel]=useState<ModelKey>("qwen");
 const [compareRunIds,setCompareRunIds]=useState<string[]>([]);const [compareResults,setCompareResults]=useState<any[]>([]);const [assessmentDrafts,setAssessmentDrafts]=useState<Record<string,any>>({});
 const [batchPlan,setBatchPlan]=useState<any>();const [batch,setBatch]=useState<Batch>();const [job,setJob]=useState<any>();const [status,setStatus]=useState("");const [error,setError]=useState("");const [lightbox,setLightbox]=useState(-1);const [elapsedNow,setElapsedNow]=useState(Date.now());
 const [projectResults,setProjectResults]=useState<RunSummary[]>([]);const [seriesInfo,setSeriesInfo]=useState<any>({active:null,items:[]});const [resultScope,setResultScope]=useState<"active"|"historical"|"hidden"|"all">("historical");const [historyScope,setHistoryScope]=useState<"active"|"historical"|"hidden"|"all">("all");const [resultFilters,setResultFilters]=useState({specimen:"",model:"",failure:""});const [resultDetail,setResultDetail]=useState<any>();
 const [evaluation,setEvaluation]=useState<any>();const [evaluationSpecimen,setEvaluationSpecimen]=useState("");const [evaluationPlan,setEvaluationPlan]=useState<any>();const [referenceData,setReferenceData]=useState<any>();const [referenceQuery,setReferenceQuery]=useState("");const [referenceDrafts,setReferenceDrafts]=useState<Record<string,any>>({});const [referencePreview,setReferencePreview]=useState<any>();const [exportRunIds,setExportRunIds]=useState<string[]>([]);
 const [evaluationVariant,setEvaluationVariant]=useState("1");const [evaluationModel,setEvaluationModel]=useState<ModelKey>("qwen");const [localDiagnostics,setLocalDiagnostics]=useState<any>();
 const [scientificPlan,setScientificPlan]=useState<any>();const [scientificRun,setScientificRun]=useState<any>();
 const [scientificRuns,setScientificRuns]=useState<any[]>([]);const [exportFiles,setExportFiles]=useState<any[]>([]);const [selectedExportIds,setSelectedExportIds]=useState<string[]>([]);
 const selectionBySpecimen=useRef<Record<string,string[]>>({});
 const selectionSaveQueue=useRef<Promise<boolean>>(Promise.resolve(true));
 const hasRunningJob=Boolean(batch?.jobs.some(item=>item.status==="running")||job?.state==="running");

 useEffect(()=>{const start=async()=>{try{while(typeof window.pywebview?.api?.bootstrap!=="function")await new Promise(r=>setTimeout(r,60));const response=await api("bootstrap");if(!response?.ok)throw new Error(response?.error||"Initialisierung fehlgeschlagen.");setBoot(response)}catch(cause){const message=cause instanceof Error?cause.message:String(cause);window.__EKI_ERROR__=message;setError(message)}finally{window.__EKI_READY__=true}};void start()},[]);
 useEffect(()=>{if(!hasRunningJob)return;const timer=window.setInterval(()=>setElapsedNow(Date.now()),1000);return()=>window.clearInterval(timer)},[hasRunningJob]);
 useEffect(()=>{if(!project)return;if(tab==="results"||tab==="export")void loadProjectResults();if(tab==="analysis"){void api("evaluation_overview").then(setEvaluation);void loadScientificRuns()}if(tab==="references_new"&&!referenceData)void loadReferenceCatalog();if(tab==="export"){void loadScientificRuns();void loadExportFiles()}},[tab,project]);

 const classes=boot?.classes||[];const chosenModels=()=>selectedModels.map(key=>({provider:modelChoices[key].provider,model:modelChoices[key].model}));
 const firstVisibleBatch=(batches:Batch[])=>batches.find(item=>item.jobs.length>0);
 const open=async(response:any)=>{if(!response.ok){setError(response.error||"");return}setProject(response.project);setSelected("");setDetail(undefined);setCheckedSpecimens([]);setCompareRunIds([]);setCompareResults([]);setBatchPlan(undefined);setBatch(undefined);setScientificPlan(undefined);setScientificRun(undefined);setProjectResults([]);setSeriesInfo({active:null,items:[]});setResultScope("historical");setResultDetail(undefined);setReferenceData(undefined);setEvaluation(undefined);setEvaluationSpecimen(response.project.specimens[0]?.id||"");setEvaluationPlan(undefined)};
 const loadProjectResults=async()=>{const response=await api("project_results");if(response.ok){setProjectResults(response.results);setSeriesInfo(response.series||{active:null,items:[]})}else setError(response.error)};
 const loadScientificRuns=async()=>{const response=await api("list_batches");if(!response?.ok){setError(response?.error||"Aufträge konnten nicht geladen werden.");return}const runs=(response.batches||[]).filter((item:any)=>item.kind==="scientific_evaluation_series");setScientificRuns(runs);const current=runs.find((item:any)=>item.status==="running")||runs[0];if(current)setScientificRun(current)};
 const loadExportFiles=async()=>{const response=await api("list_export_files");if(response?.ok)setExportFiles(response.files||[]);else setError(response?.error||"Exportdateien konnten nicht geladen werden.")};
 const loadComparison=async(ids:string[])=>{const responses=await Promise.all(ids.map(runId=>api("result_detail",{runId})));const valid=responses.filter(item=>item.ok);setCompareResults(valid);setAssessmentDrafts(current=>{const next={...current};for(const item of valid)next[item.runId]=next[item.runId]||initialAssessment(item);return next})};
 const load=async(id:string)=>{await selectionSaveQueue.current;setSelected(id);const response=await api("specimen_detail",{specimen:id});if(!response.ok){setError(response.error);return}selectionBySpecimen.current[id]=response.images.filter((image:ImageItem)=>image.analysisSelected).map((image:ImageItem)=>image.name);setDetail(response);const initial=(response.history||[]).filter((run:RunSummary)=>!run.hidden).slice(-3).reverse().map((run:RunSummary)=>run.runId);setCompareRunIds(initial);await loadComparison(initial)};
 const refresh=async()=>{if(!project)return;const response=await api("project_snapshot");if(response.ok)setProject(response.project);if(selected)await load(selected);await loadProjectResults()};
 const createProject=async()=>{const name=prompt("Projektname");if(name)await open(await api("create_project",{name}))};
 const quickUpload=async()=>{const name=prompt("Name des neuen Projekts");if(!name)return;const created=await api("create_project",{name});if(!created.ok){setError(created.error);return}setProject(created.project);const id=prompt("Prüfkörpernummer für die Bilder");if(!id)return;const specimen=await api("create_specimen",{specimen:id});if(!specimen.ok){setError(specimen.error);return}setProject(specimen.project);setSelected(id);const imported=await api("import_images",{specimen:id});if(imported.ok)await load(id)};
 const createSpecimen=async()=>{const id=prompt("Eindeutige Prüfkörpernummer");if(!id)return;const response=await api("create_specimen",{specimen:id});if(response.ok){setProject(response.project);await load(id)}else setError(response.error)};
 const importImages=async()=>{if(!selected)return;const response=await api("import_images",{specimen:selected});if(response.ok)await load(selected);else if(!response.cancelled)setError(response.error)};
 const loadReferenceCatalog=async()=>{const response=await api("reference_catalog");if(!response?.ok){setError(response?.error||"Referenzdatenbank konnte nicht geladen werden.");return}setReferenceData(response);setReferenceDrafts({})};
 const addReferenceImages=async(code:string)=>{const specimenId=prompt("Prüfkörper-ID der neuen Referenzbilder");if(!specimenId)return;const description=prompt("Kurze fachliche Bildbeschreibung (optional)")||"";const confirmed=confirm("Sollen die Bilder sofort fachlich bestätigt gespeichert werden?\n\nAbbrechen = zunächst unbestätigt speichern.");const response=await api("choose_reference_images",{code,specimenId,description,confirmed});if(response.ok){setReferenceData(response.catalog);setReferenceDrafts({});setStatus(`${response.imported.length} Referenzbilder importiert; ${response.duplicates.length} Duplikate nicht erneut gespeichert.`)}else if(!response.cancelled)setError(response.error)};
 const referenceDraft=(item:any)=>referenceDrafts[item.id]||{code:item.code,specimenId:item.specimenId||"",description:item.description||"",confirmed:Boolean(item.confirmed)};
 const patchReferenceDraft=(item:any,patch:any)=>setReferenceDrafts(current=>({...current,[item.id]:{...referenceDraft(item),...patch}}));
 const saveReferenceEntry=async(item:any)=>{const draft=referenceDraft(item);const protectedChange=Boolean(item.confirmed)&&(draft.code!==item.code||draft.specimenId!==(item.specimenId||"")||draft.description!==(item.description||"")||!draft.confirmed);const confirmConfirmedChange=protectedChange?confirm("Dieser Eintrag ist bereits bestätigt. Fachliche Änderung ausdrücklich durchführen?"):false;if(protectedChange&&!confirmConfirmedChange)return;const response=await api("update_reference_entry",{id:item.id,...draft,confirmConfirmedChange});if(response.ok){setReferenceData(response.catalog);setReferenceDrafts({});setStatus("Referenzbildeintrag nachvollziehbar gespeichert.")}else setError(response.error)};
 const saveImageSelection=(id:string,names:string[])=>{selectionBySpecimen.current[id]=names;setDetail(current=>current?.specimen===id?{...current,images:current.images.map(image=>({...image,analysisSelected:image.analysisEligible&&names.includes(image.name)}))}:current);selectionSaveQueue.current=selectionSaveQueue.current.then(async()=>{try{const response=await api("save_image_selection",{specimen:id,selectedImages:names});if(!response?.ok){setError(response?.error||"Bildauswahl konnte nicht gespeichert werden.");return false}return true}catch(cause){setError(`Bildauswahl konnte nicht gespeichert werden: ${cause instanceof Error?cause.message:String(cause)}`);return false}});return selectionSaveQueue.current};
 const toggleImage=(image:ImageItem)=>{if(!detail||!image.analysisEligible)return;const current=selectionBySpecimen.current[detail.specimen]||[];void saveImageSelection(detail.specimen,current.includes(image.name)?current.filter(item=>item!==image.name):[...current,image.name])};
 const setAllImages=(value:boolean)=>{if(detail)void saveImageSelection(detail.specimen,value?detail.images.filter(image=>image.analysisEligible).map(image=>image.name):[])};
 const confirmCurrentSelection=async()=>{if(!detail)return;const names=detail.images.filter(image=>image.analysisSelected&&image.analysisEligible).map(image=>image.name);if(await saveImageSelection(detail.specimen,names))setStatus(`Bildauswahl für ${detail.specimen} manuell bestätigt.`)};
 const toggleSpecimen=(id:string)=>{setCheckedSpecimens(current=>current.includes(id)?current.filter(item=>item!==id):[...current,id]);setScientificPlan(undefined)};const toggleModel=(key:ModelKey)=>setSelectedModels(current=>current.includes(key)?current.filter(item=>item!==key):[...current,key]);
 const plan=async()=>{if(!await selectionSaveQueue.current)return;const response=await api("plan_batch",{specimenIds:checkedSpecimens,models:chosenModels()});if(response.ok)setBatchPlan(response.plan);else setError(response.error)};
 const pollBatch=async(batchId:string)=>{const response=await api("batch_status",{batchId});if(!response.ok){setError(response.error);return}setBatch(response.batch);if(response.batch.status==="running")setTimeout(()=>void pollBatch(batchId),1000);else{setStatus("Batch abgeschlossen.");await refresh()}};
 const startBatch=async()=>{if(!await selectionSaveQueue.current)return;const planned=await api("plan_batch",{specimenIds:checkedSpecimens,models:chosenModels()});if(!planned.ok){setError(planned.error);return}setBatchPlan(planned.plan);let confirmCloud=false;if(planned.plan.cloudRequestCount){confirmCloud=confirm(`${planned.plan.cloudRequestCount} geplante Cloud-Anfragen können Kosten verursachen. Ausgewählte Bilder werden übertragen. Jetzt freigeben?`);if(!confirmCloud)return}const response=await api("start_batch",{specimenIds:checkedSpecimens,models:chosenModels(),confirmCloud});if(!response.ok){setError(response.error);return}setBatch(response.batch);void pollBatch(response.batchId)};
 const pollJob=async(jobId:string)=>{try{const response=await api("analysis_status",{jobId});if(!response?.ok){setJob({state:"error"});setError(response?.error||"Der Analysestatus konnte nicht gelesen werden.");return}setJob(response);if(response.state==="running")setTimeout(()=>void pollJob(jobId),750);else if(response.state==="complete"){setStatus("Analyse abgeschlossen.");await refresh()}else setError(response.error||"Analyse fehlgeschlagen.")}catch(cause){setJob({state:"error"});setError(`Der Analysestatus konnte nicht gelesen werden: ${cause instanceof Error?cause.message:String(cause)}`)}};
 const startSingle=async()=>{if(!detail||job?.state==="running")return;const choice=modelChoices[singleModel];let confirmPaid=false;if(choice.cloud){confirmPaid=confirm(`Der Aufruf von ${choice.label} kann Kosten verursachen und überträgt die ausgewählten Bilder. Jetzt freigeben?`);if(!confirmPaid)return}setError("");setStatus("Bildauswahl wird gespeichert …");if(!await selectionSaveQueue.current){setStatus("");return}setStatus("Analyseauftrag wird gestartet …");try{const response=await api("start_analysis",{specimen:detail.specimen,provider:choice.provider,model:choice.model,confirmPaid});if(!response?.ok){setJob({state:"error"});setStatus("");setError(response?.error||"Die Analyse konnte nicht gestartet werden.");return}setJob({state:"running",status:"Modell wird geladen",startedAt:new Date().toISOString()});void pollJob(response.jobId)}catch(cause){setJob({state:"error"});setStatus("");setError(`Die Analyse konnte nicht gestartet werden: ${cause instanceof Error?cause.message:String(cause)}`)}};
 const planEvaluationRun=async()=>{if(!evaluationSpecimen){setError("Bitte einen Prüfkörper auswählen.");return}if(!await selectionSaveQueue.current)return;const choice=modelChoices[evaluationModel];const response=await api("evaluation_run_plan",{specimen:evaluationSpecimen,variant:evaluationVariant,provider:choice.provider,model:choice.model});if(response.ok){setEvaluationPlan(response.plan);setStatus("Kontrollübersicht erstellt. Noch kein Modellaufruf.")}else setError(response.error)};
 const loadLocalDiagnostics=async()=>{if(evaluationModel!=="qwen")return;const response=await api("local_model_diagnostics",{specimen:evaluationSpecimen,model:modelChoices.qwen.model});if(response?.ok)setLocalDiagnostics(response);else setError(response?.error||"Lokale Modelldiagnose konnte nicht geladen werden.")};
 const prepareEvaluationMemory=async()=>{const choice=modelChoices[evaluationModel];if(choice.cloud){setError("Cloud-Referenzvorbereitung bleibt gesperrt; es wurde kein API-Aufruf ausgeführt.");return}const response=await api("prepare_evaluation_memory",{variant:evaluationVariant,provider:choice.provider,model:choice.model});if(!response.ok){setError(response.error);return}setJob({state:"running",status:"Referenzwissen wird vorbereitet",startedAt:new Date().toISOString()});setEvaluationPlan(undefined);void pollJob(response.jobId)};
 const startEvaluationRun=async()=>{if(!evaluationSpecimen){setError("Bitte einen Prüfkörper auswählen.");return}if(!seriesInfo.active){setError("Bitte zuerst eine wissenschaftliche Testreihe beginnen.");return}if(!await selectionSaveQueue.current)return;const choice=modelChoices[evaluationModel];setError("");setStatus("Ordnerstruktur, Variante und Referenzdaten werden geprüft …");const planned=await api("evaluation_run_plan",{specimen:evaluationSpecimen,variant:evaluationVariant,provider:choice.provider,model:choice.model});if(!planned.ok){setStatus("");setError(planned.error);return}const currentPlan=planned.plan;setEvaluationPlan(currentPlan);if(!currentPlan.structureReady){const missing=Object.keys(currentPlan.missingByClass||{});const details=[missing.length?`Für folgende Merkmale fehlen Referenzbilder: ${missing.join(", ")}.`:"",...(currentPlan.errors||[])].filter(Boolean).join(" ");setStatus("");setError(`Variante ${evaluationVariant} ist noch nicht bereit. ${details}`.trim());return}if(!currentPlan.memory?.prepared){setStatus("");setError(`Variante ${evaluationVariant} ist strukturell bereit, das Referenzwissen ist aber noch nicht vorbereitet. Öffnen Sie „Technische Details anzeigen“.`);return}let confirmPaid=false;if(choice.cloud){confirmPaid=confirm(`${choice.label} ist ein Cloud-Modell und kann Kosten verursachen. Ausgewählte Bilder und die für Variante ${evaluationVariant} vorgesehenen Daten werden übertragen. Analyse ausdrücklich starten?`);if(!confirmPaid){setStatus("");return}}setStatus(`Variante ${evaluationVariant} wird gestartet …`);const response=await api("start_analysis",{specimen:evaluationSpecimen,provider:choice.provider,model:choice.model,confirmPaid,evaluationVariant,evaluationPlanToken:currentPlan.planToken});if(!response.ok){setStatus("");setError(response.error);return}setJob({state:"running",status:"Modell wird geladen",startedAt:new Date().toISOString()});setEvaluationPlan(undefined);void pollJob(response.jobId)};
 const cancelWaiting=async()=>{if(!batch)return;const response=await api("cancel_batch_jobs",{batchId:batch.batchId});if(response.ok)setBatch(response.batch);else setError(response.error)};const resumeBatch=async()=>{if(!batch)return;const response=await api("resume_batch",{batchId:batch.batchId,retryFailed:true});if(response.ok){setBatch(response.batch);void pollBatch(batch.batchId)}else setError(response.error)};
 const dismissBatchJob=async(jobId:string)=>{if(!batch)return;const response=await api("dismiss_batch_jobs",{batchId:batch.batchId,jobIds:[jobId]});if(!response.ok){setError(response.error);return}const listed=await api("list_batches");setBatch(listed.ok?firstVisibleBatch(listed.batches):response.batch.jobs.length?response.batch:undefined);setStatus("Anzeigeeintrag entfernt. Gespeicherte Analysen und Dateien bleiben erhalten.")};
 const clearBatchHistory=async()=>{if(!confirm("Nur abgeschlossene, fehlgeschlagene und abgebrochene Anzeigeeinträge ausblenden?\n\nKI-Ergebnisse, Bilder, Prüfprotokolle, Bewertungen und vollständige Batch-Manifeste bleiben gespeichert."))return;const response=await api("clear_batch_history");if(!response.ok){setError(response.error);return}setBatch(firstVisibleBatch(response.batches));setStatus(`${response.dismissedCount} Anzeigeeinträge entfernt. Gespeicherte Analyseartefakte wurden nicht gelöscht.`)};
 const toggleCompare=async(runId:string)=>{const next=compareRunIds.includes(runId)?compareRunIds.filter(id=>id!==runId):[runId,...compareRunIds];if(next.length>3){setError("Es können höchstens drei Analyseläufe gleichzeitig verglichen werden.");return}setCompareRunIds(next);await loadComparison(next)};
 const updateAssessment=(runId:string,patch:any)=>setAssessmentDrafts(current=>({...current,[runId]:{...current[runId],...patch}}));
 const saveAssessment=async(runId:string)=>{const response=await api("save_assessment",{runId,...assessmentDrafts[runId]});if(!response.ok){setError(response.error);return}setStatus("Fachliche Bewertung separat gespeichert.");await loadComparison(compareRunIds);await loadProjectResults();if(resultDetail?.runId===runId)setResultDetail(await api("result_detail",{runId}))};
 const showResult=async(runId:string)=>{const response=await api("result_detail",{runId});if(!response.ok){setError(response.error);return}setResultDetail(response);setAssessmentDrafts(current=>({...current,[runId]:current[runId]||initialAssessment(response)}))};
 const setRunVisibility=async(run:RunSummary,hidden:boolean)=>{const response=await api("set_result_visibility",{runId:run.runId,hidden});if(!response.ok){setError(response.error);return}const nextIds=compareRunIds.filter(id=>id!==run.runId);setCompareRunIds(nextIds);await loadComparison(nextIds);if(resultDetail?.runId===run.runId)setResultDetail(undefined);if(detail)await load(detail.specimen);await loadProjectResults();const snapshot=await api("project_snapshot");if(snapshot.ok)setProject(snapshot.project);setStatus(hidden?"Analyselauf aus der sichtbaren Historie ausgeblendet.":"Analyselauf wiederhergestellt.")};
 const deleteRun=async(run:RunSummary)=>{if(!confirm(`Analyselauf ${run.model} vom ${dateLabel(run.createdAt)} endgültig löschen?\n\nGelöscht wird nur dieses KI-Testergebnis. Originalbilder, Referenzdatenbank, Expertenbewertungen, Testreihen und offizielle historische Daten bleiben erhalten.`))return;const response=await api("delete_analysis_run",{runId:run.runId,confirmDeletion:true});if(!response.ok){setError(response.error);return}const nextIds=compareRunIds.filter(id=>id!==run.runId);setCompareRunIds(nextIds);await loadComparison(nextIds);if(resultDetail?.runId===run.runId)setResultDetail(undefined);setExportRunIds(current=>current.filter(id=>id!==run.runId));if(detail)await load(detail.specimen);await loadProjectResults();const snapshot=await api("project_snapshot");if(snapshot.ok)setProject(snapshot.project);setStatus("KI-Analyselauf gelöscht. Bilder, Referenzen und fachliche Bewertungen blieben unverändert.")};
 const deleteAllSpecimenRuns=async()=>{if(!detail?.history.length)return;if(!confirm(`Alle ${detail.history.length} KI-Analyseläufe für ${detail.specimen} endgültig löschen?\n\nDies betrifft historische Entwicklungstests und wissenschaftliche KI-Ergebnisse dieses Prüfkörpers. Originalbilder, Referenzdatenbank, Expertenbewertungen, Testreihen und offizielle historische Daten bleiben erhalten.`))return;const response=await api("delete_specimen_analysis_runs",{specimen:detail.specimen,confirmDeletion:true});if(!response.ok){setError(response.error);return}const deleted=new Set<string>(response.deletedRunIds||[]);setCompareRunIds(current=>current.filter(id=>!deleted.has(id)));setCompareResults(current=>current.filter(item=>!deleted.has(item.runId)));setExportRunIds(current=>current.filter(id=>!deleted.has(id)));if(resultDetail?.runId&&deleted.has(resultDetail.runId))setResultDetail(undefined);await load(detail.specimen);await loadProjectResults();const snapshot=await api("project_snapshot");if(snapshot.ok)setProject(snapshot.project);setStatus(`${response.deletedCount} KI-Analyseläufe gelöscht. Geschützte Daten blieben unverändert.`)};
 const resetTestHistory=async()=>{if(!detail)return;if(!confirm(`Entwicklungstest-Historie für ${detail.specimen} zurücksetzen?\n\nErgebnisdateien, Modellantworten, Expertenbewertungen und wissenschaftliche Testreihen bleiben unverändert.`))return;const response=await api("reset_test_history",{specimen:detail.specimen});if(!response.ok){setError(response.error);return}setCompareRunIds([]);setCompareResults([]);await load(detail.specimen);await loadProjectResults();const snapshot=await api("project_snapshot");if(snapshot.ok)setProject(snapshot.project);setStatus(`${response.hiddenCount} Entwicklungsläufe ausgeblendet. Wissenschaftliche Ergebnisse wurden nicht verändert.`)};
 const exportSelected=async()=>{const response=await api("export_selected_runs",{runIds:exportRunIds});if(response.ok)setStatus(`Export erstellt: ${response.csvPath}`);else setError(response.error)};
 const beginTestSeries=async()=>{const name=prompt("Name der neuen wissenschaftlichen Testreihe",`Wissenschaftliche Testreihe ${new Date().toLocaleDateString("de-AT")}`);if(name===null)return;const response=await api("begin_test_series",{name});if(!response.ok){setError(response.error);return}setSeriesInfo((current:any)=>({active:response.series,items:[response.series,...(current.items||[])]}));setScientificPlan(undefined);setScientificRun(undefined);setResultScope("active");setResultDetail(undefined);setCompareRunIds([]);setCompareResults([]);setExportRunIds([]);setStatus(`Neue Testreihe begonnen: ${response.series.name}. Historische Ergebnisse bleiben erhalten.`)};
 const planScientificSeries=async()=>{if(!checkedSpecimens.length){setError("Bitte mindestens einen Prüfkörper auswählen.");return}if(!await selectionSaveQueue.current)return;const choice=modelChoices[evaluationModel];const response=await api("scientific_series_plan",{specimenIds:checkedSpecimens,variant:evaluationVariant,provider:choice.provider,model:choice.model});if(response.ok){setScientificPlan(response.plan);setSeriesInfo((current:any)=>({...current,active:response.plan.testSeries}));setStatus(response.plan.readyToStart?"Plan geprüft und startbereit. Noch kein Modellaufruf.":"Plan geprüft; offene Punkte verhindern den Start.")}else setError(response.error)};
 const pollScientificSeries=async(seriesRunId:string)=>{const response=await api("scientific_series_status",{seriesRunId});if(!response.ok){setError(response.error);return}setScientificRun(response.batch);if(response.batch.status==="running")setTimeout(()=>void pollScientificSeries(seriesRunId),1000);else{setStatus("Wissenschaftliche Serienprüfung beendet. Ergebnisse und Fehler sind gespeichert.");await refresh()}};
 const startScientificSeries=async()=>{if(!scientificPlan?.readyToStart)return;const choice=modelChoices[evaluationModel];let confirmCloud=false;if(choice.cloud){confirmCloud=confirm(`${choice.label}: ${scientificPlan.estimatedPartialRequestCount} geplante Cloud-Anfragen können Kosten verursachen. Die fixierten Bilder werden übertragen. Jetzt starten?`);if(!confirmCloud)return}const response=await api("start_scientific_series",{planToken:scientificPlan.planToken,confirmCloud});if(!response.ok){setError(response.error);return}setScientificRun(response.batch);setScientificPlan(undefined);void pollScientificSeries(response.seriesRunId)};
 const resumeScientificSeries=async()=>{if(!scientificRun)return;const response=await api("resume_scientific_series",{seriesRunId:scientificRun.seriesRunId});if(!response.ok){setError(response.error);return}setScientificRun(response.batch);void pollScientificSeries(scientificRun.seriesRunId)};
 const cancelScientificSeries=async()=>{if(!scientificRun)return;if(!confirm("Lauf kontrolliert abbrechen? Eine bereits laufende Modellanfrage wird noch abgeschlossen; erfolgreiche Teilergebnisse bleiben gespeichert."))return;const response=await api("cancel_batch_jobs",{batchId:scientificRun.batchId});if(response.ok){setScientificRun(response.batch);setStatus("Abbruch angefordert. Gespeicherte Ergebnisse bleiben erhalten.")}else setError(response.error)};
 const exportScientificSeries=async()=>{if(!scientificRun)return;const response=await api("export_scientific_series",{seriesRunId:scientificRun.seriesRunId});if(response.ok)setStatus(`CSV-Exporte erstellt: ${response.wideCsvPath} und ${response.detailCsvPath}`);else setError(response.error)};
 const exportSeries=async(run:any)=>{const response=await api("export_scientific_series",{seriesRunId:run.seriesRunId||run.batchId});if(response.ok){setStatus("Übersichts-CSV, Detail-CSV und Exportmanifest wurden erstellt.");await loadExportFiles()}else setError(response.error)};
 const deleteExports=async(deleteAll=false)=>{const ids=deleteAll?exportFiles.map(item=>item.exportId):selectedExportIds;if(!ids.length)return;if(!confirm(deleteAll?`Alle ${exportFiles.length} generierten Exportkopien löschen? Rohanalysen, Testreihen und Bilder bleiben erhalten.`:`${ids.length} ausgewählte Exportkopien löschen? Rohanalysen, Testreihen und Bilder bleiben erhalten.`))return;const response=await api("delete_export_files",{exportIds:ids,deleteAll,confirmDeletion:true});if(response.ok){setExportFiles(response.files||[]);setSelectedExportIds([]);setStatus(`${response.deletedCount} Exportdateien gelöscht. Sie können aus den Ergebnissen neu erzeugt werden.`)}else setError(response.error)};

 const fieldFilteredResults=useMemo(()=>projectResults.filter(run=>(!resultFilters.specimen||run.specimenId===resultFilters.specimen)&&(!resultFilters.model||run.model===resultFilters.model)&&(!resultFilters.failure||run.detectedCodes?.includes(resultFilters.failure))),[projectResults,resultFilters]);
 const filteredResults=useMemo(()=>fieldFilteredResults.filter(run=>resultScope==="hidden"?run.hidden:!run.hidden&&(resultScope==="all"||(resultScope==="historical"&&!run.seriesId)||(resultScope==="active"&&Boolean(seriesInfo.active)&&run.seriesId===seriesInfo.active.seriesId))),[fieldFilteredResults,resultScope,seriesInfo.active]);
 const filteredHistory=useMemo(()=>detail?.history.filter(run=>historyScope==="hidden"?run.hidden:!run.hidden&&(historyScope==="all"||(historyScope==="historical"&&!run.seriesId)||(historyScope==="active"&&Boolean(seriesInfo.active)&&run.seriesId===seriesInfo.active.seriesId)))||[],[detail,historyScope,seriesInfo.active]);
 const filteredReferences=useMemo(()=>referenceData?.classes?.filter((entry:any)=>`${entry.code} ${entry.name} ${entry.definition}`.toLocaleLowerCase("de").includes(referenceQuery.toLocaleLowerCase("de")))||[],[referenceData,referenceQuery]);
 const lightboxIndex=useMemo(()=>detail?.images.findIndex((_,index)=>index===lightbox)??-1,[detail,lightbox]);
 const selectedEvaluationVariant=evaluation?.variants?.find((item:any)=>item.variantId===evaluationVariant);
 const missingEvaluationFeatures=Object.keys(selectedEvaluationVariant?.missingByClass||{});

 if(!boot)return <div className="loading-page">{error?<div className="error"><b>Start fehlgeschlagen</b><p>{error}</p></div>:"KI-Bildanalyse wird geladen …"}</div>;
 if(!project)return <main className="welcome"><img src={widget}/><h1>KI-Bildanalyse</h1><p>Visuelle Klassifikation von Holzprüfkörpern</p><div className="welcome-actions"><button className="primary" onClick={async()=>open(await api("open_example"))}>Beispielprojekt Test_001 öffnen</button><button onClick={async()=>open(await api("choose_project"))}>Bestehendes Projekt öffnen</button><button onClick={createProject}>Neues Projekt erstellen</button><button onClick={quickUpload}>Einzelne Bilder hochladen</button></div>{error&&<div className="error">{error}</div>}</main>;

 const runMenu=(run:RunSummary)=><details className="run-menu"><summary aria-label={`Menü für ${run.model}`}>⋯</summary><div><button onClick={()=>void setRunVisibility(run,!run.hidden)}>{run.hidden?"Wiederherstellen":"Aus Historie ausblenden"}</button><button className="danger" onClick={()=>void deleteRun(run)}>Analyselauf löschen</button></div></details>;
 const resultTable=(selectable:boolean,rows:RunSummary[]=filteredResults)=><div className="result-table"><div className="result-row result-head-row">{selectable&&<span/>}<b>Prüfkörper / Testreihe</b><b>Modell / Variante</b><b>KI-Merkmale</b><b>Technischer Status</b><b>Datum / Laufzeit</b><b aria-label="Aktionen"/></div>{rows.map(run=><div className={`result-row ${run.hidden?"hidden-run":""}`} key={run.runId}>{selectable&&<input type="checkbox" checked={exportRunIds.includes(run.runId)} onChange={()=>setExportRunIds(current=>current.includes(run.runId)?current.filter(id=>id!==run.runId):[...current,run.runId])}/>}<button onClick={()=>void showResult(run.runId)}>{run.specimenId}<small>{run.seriesName||"Historischer Entwicklungstest"}</small></button><span>{run.provider} · {run.model}<small>{run.evaluationVariant?`Variante ${run.evaluationVariant}`:"Historischer Lauf"}</small></span><span>{run.detectedCodes?.join(", ")||run.status}<small>{run.featureCount} gleichrangige Vorschläge{run.legacy?" · historisches Format":""}</small></span><span className={run.status==="KLASSIFIZIERT"||run.status==="KEINE_MERKMALE"?"reviewed":"unreviewed"}>{run.status}<small>{run.assessment?.schemaVersion==="2.0"?"Fachlich geprüft":"Fachprüfung offen"}</small></span><span>{dateLabel(run.createdAt)}<small>{run.durationSeconds??"–"} s</small></span>{runMenu(run)}</div>)}</div>;

 return <div className="app">
  <header><div className="brand"><img src={logo} alt="holz.bau forschungs gmbh"/></div><div><h1>KI-Bildanalyse</h1><p>{project.name} · {project.path}</p></div><button onClick={()=>setProject(undefined)}>Projekt wechseln</button></header>
  <nav className="tabs">{tabs.map(([key,label])=><button className={tab===key?"active":""} onClick={()=>setTab(key)} key={key}>{label}</button>)}</nav>
  {tab==="references_new"&&<ReferenceDatabase data={referenceData} onData={setReferenceData} onError={setError} onStatus={setStatus}/>}
  {Boolean(false)&&<main className="tab-page evaluation-workspace">
   <div className="page-title"><div><h2>Wissenschaftliche Evaluation</h2><p>Versuchsreihe auswählen und Analyse mit einem zentralen Start ausführen.</p></div><button className="primary" onClick={beginTestSeries}>Neue Testreihe beginnen</button></div>
   <section className="evaluation-selectors simplified">
    <label>Testreihe<strong>{seriesInfo.active?.name||"Noch keine aktive Testreihe"}</strong></label>
    <label>Evaluationsvariante<select value={evaluationVariant} onChange={event=>{setEvaluationVariant(event.target.value);setEvaluationPlan(undefined)}}>{["1","2","2a","3"].map(id=><option value={id} key={id}>Variante {id}: {evaluationVariantLabels[id]}</option>)}</select></label>
    <label>Prüfkörper<select value={evaluationSpecimen} onChange={event=>{setEvaluationSpecimen(event.target.value);setEvaluationPlan(undefined);setLocalDiagnostics(undefined)}}>{project.specimens.map(item=><option value={item.id} key={item.id}>{item.id}</option>)}</select></label>
    <label>KI-Modell<select value={evaluationModel} onChange={event=>{setEvaluationModel(event.target.value as ModelKey);setEvaluationPlan(undefined);setLocalDiagnostics(undefined)}}>{(Object.keys(modelChoices) as ModelKey[]).map(key=><option value={key} key={key}>{modelChoices[key].label}</option>)}</select></label>
   </section>
   <section className="scientific-series-card">
    <header><div><span>WISSENSCHAFTLICHER SERIENLAUF</span><h3>Z-30 · 49 Prüfkörper · ohne Prüfkörper 30</h3></div><b>{scientificRun?.status||"NOCH NICHT GESTARTET"}</b></header>
    <p>Verwendet ausschließlich die bereits manuell bestätigte Bildauswahl. Nummernfotos, Ground Truth, Prüfprotokolle, frühere KI-Ergebnisse und fachliche Bewertungen werden nicht an das Modell übergeben.</p>
    <div className="evaluation-actions"><button disabled={!seriesInfo.active||scientificRun?.status==="running"} onClick={planScientificSeries}>Bildauswahl und Serienplan prüfen</button><button className="primary" disabled={!scientificPlan||scientificRun?.status==="running"} onClick={startScientificSeries}>Serienprüfung starten</button><button disabled={!scientificRun||!["interrupted","paused","completed_with_errors"].includes(scientificRun.status)} onClick={resumeScientificSeries}>Ausstehende Teilanfragen fortsetzen</button><button disabled={!scientificRun} onClick={exportScientificSeries}>Beide CSV exportieren</button></div>
    {scientificPlan&&<div className="scientific-plan-summary"><b>{scientificPlan.specimenCount} Prüfkörper · {scientificPlan.selectedImageCount} fixierbare Bilder</b><span>Variante {scientificPlan.variant} · {scientificPlan.provider} · {scientificPlan.model}</span><span>{scientificPlan.estimatedPartialRequestCount} geplante Teilanfragen · Bildlimit je Anfrage: {scientificPlan.providerImageLimit??"kein festes Limit im Providerpfad"}</span><span>Regelwerk {scientificPlan.classificationRulesVersion} · Prompt {scientificPlan.promptVersion}</span><details><summary>Bildauswahl je Prüfkörper anzeigen</summary><div className="scientific-selection-list">{scientificPlan.specimens.map((item:any)=><div key={item.specimen}><b>{item.specimen}</b><span>{item.selectedImageCount} Bilder</span><small>{item.images.map((image:any)=>image.filename).join(", ")}</small></div>)}</div></details></div>}
    {scientificRun&&<div className="scientific-progress"><progress max={scientificRun.jobCount} value={scientificRun.jobs.filter((item:any)=>["succeeded","partially_succeeded","failed","cancelled"].includes(item.status)).length}/><span>{scientificRun.jobs.filter((item:any)=>item.status==="succeeded").length} erfolgreich · {scientificRun.jobs.filter((item:any)=>item.status==="partially_succeeded").length} teilweise · {scientificRun.jobs.filter((item:any)=>item.status==="failed").length} fehlgeschlagen · {scientificRun.jobs.filter((item:any)=>["interrupted","paused"].includes(item.status)).length} ausstehend/pausiert</span><div className="scientific-selection-list">{scientificRun.jobs.map((item:any)=><div key={item.jobId}><b>{item.specimen}</b><span>{statusLabels[item.status]||item.status}</span><small>{item.statusText||item.error||`${item.selectedImageCount??item.selectedImages?.length??0} Bilder · ${item.partialRequestCount??1} Teilanfragen · Zusammenführung: ${item.mergeStatus||"ausstehend"}`}</small></div>)}</div></div>}
   </section>
   {selectedEvaluationVariant&&<section className={`evaluation-start-card ${selectedEvaluationVariant.ready?"ready":"not-ready"}`}>
    <header><div><span>VARIANTE {evaluationVariant}</span><h3>{evaluationVariantLabels[evaluationVariant]}</h3></div><b>{selectedEvaluationVariant.ready?"BEREIT":"NICHT BEREIT"}</b></header>
    <p>{evaluationVariantDescriptions[evaluationVariant]}</p>
    {!selectedEvaluationVariant.ready&&<div className="evaluation-readiness-message"><p>Variante {evaluationVariant} ist noch nicht bereit. {missingEvaluationFeatures.length?`Für folgende Merkmale fehlen Referenzbilder: ${missingEvaluationFeatures.join(", ")}.`:"Erforderliche Dateien oder Beschreibungen fehlen."}</p>{selectedEvaluationVariant.errors?.length>0&&<ul>{selectedEvaluationVariant.errors.map((text:string)=><li key={text}>{text}</li>)}</ul>}<button onClick={()=>setTab("references_new")}>Referenzdatenbank öffnen</button></div>}
    <button className="evaluation-start-button" disabled={!seriesInfo.active||!selectedEvaluationVariant.ready||job?.state==="running"} onClick={startEvaluationRun}>Analyse starten</button>
   </section>}
   <details className="evaluation-technical-details" onToggle={event=>{if(event.currentTarget.open)void loadLocalDiagnostics()}}>
    <summary>Technische Details anzeigen</summary>
    <div className="evaluation-actions"><button onClick={async()=>setEvaluation(await api("evaluation_overview"))}>Struktur prüfen</button><button disabled={evaluationVariant==="1"||!selectedEvaluationVariant?.ready||evaluationModel!=="qwen"||job?.state==="running"} onClick={prepareEvaluationMemory}>Referenzwissen vorbereiten</button><button disabled={!seriesInfo.active} onClick={planEvaluationRun}>Kontrollübersicht erstellen</button></div>
    {selectedEvaluationVariant&&<dl className="technical-evaluation-data"><dt>Referenzordnerzugriff</dt><dd>{evaluationVariant==="1"?"Nein":selectedEvaluationVariant.referenceRoot}</dd><dt>Unveränderte Referenzen</dt><dd>{evaluationVariant==="3"?0:selectedEvaluationVariant.referenceCount}</dd><dt>Annotierte Referenzen</dt><dd>{evaluationVariant==="3"?selectedEvaluationVariant.referenceCount:0}</dd><dt>Referenzbatches</dt><dd>{selectedEvaluationVariant.referenceBatchCount}</dd><dt>Beschreibungen vollständig</dt><dd>{selectedEvaluationVariant.descriptionsComplete?"Ja":"Nein"}</dd><dt>Modelltyp</dt><dd>{modelChoices[evaluationModel].cloud?"Cloud-Modell":"Lokales Modell"}</dd></dl>}
    {Object.keys(selectedEvaluationVariant?.countsByClass||{}).length>0&&<div className="class-counts">{Object.entries(selectedEvaluationVariant.countsByClass).map(([code,count])=><span key={code}>{code}: {String(count)}</span>)}</div>}
    {evaluationModel==="qwen"&&localDiagnostics&&<section className="local-model-diagnostics"><h3>Lokale Modelldiagnose</h3><dl><dt>Modell / Kennung</dt><dd>{localDiagnostics.model} · {localDiagnostics.latestRun?.actualModel||"noch kein Lauf"}</dd><dt>Modellstatus</dt><dd>{localDiagnostics.endpointReachable?(localDiagnostics.modelInstalled?"Ollama erreichbar · Modell installiert":"Ollama erreichbar · Modell fehlt"):"Ollama nicht erreichbar"}</dd><dt>Tatsächlich ausgewählte Bilder</dt><dd>{localDiagnostics.selectedImageCount}</dd><dt>Bilder im letzten Lauf</dt><dd>{localDiagnostics.latestRun?.imageCount??"Kein Lauf"}</dd><dt>Aktive Merkmalsklassen</dt><dd>{localDiagnostics.activeClassCount}: {localDiagnostics.activeClassCodes.join(", ")}</dd><dt>Letzte Promptversion</dt><dd>{localDiagnostics.latestRun?.promptVersion||"Kein Lauf"}</dd><dt>Letzter Modellstatus</dt><dd>{localDiagnostics.latestRun?.status||"Kein Lauf"}{localDiagnostics.latestRun?.analysisOutcome?` · ${localDiagnostics.latestRun.analysisOutcome}`:""}</dd><dt>Technik / Parsing</dt><dd>{localDiagnostics.endpointError||localDiagnostics.latestRun?.validationStatus||"Keine gespeicherte Parsing-Diagnose"}</dd></dl>{localDiagnostics.latestRun?.rawResponse&&<details><summary>Modellrohantwort anzeigen</summary><pre>{localDiagnostics.latestRun.rawResponse}</pre></details>}</section>}
    {evaluationPlan&&<section className="control-overview"><header><div><span>AKTUELLE KONTROLLÜBERSICHT</span><h3>{evaluationPlan.specimen} · Variante {evaluationPlan.variant}</h3></div><b>{evaluationPlan.structureReady&&evaluationPlan.memory?.prepared?"BEREIT":"NICHT BEREIT"}</b></header><dl><dt>Provider / Modell</dt><dd>{evaluationPlan.provider} · {evaluationPlan.model}</dd><dt>Prüfkörperbilder</dt><dd>{evaluationPlan.imageCount}: {evaluationPlan.images.join(", ")}</dd><dt>Referenzen / Batches</dt><dd>{evaluationPlan.referenceImages} / {evaluationPlan.referenceBatches}</dd>{evaluationPlan.variant==="3"&&<><dt>Annotierte Bilder</dt><dd>{evaluationPlan.annotatedImages}</dd><dt>Quellenzuordnung</dt><dd>{evaluationPlan.sourceLinksComplete?"Vollständig":"Unvollständig"}</dd><dt>Fachlich geprüft</dt><dd>{evaluationPlan.reviewRequired?(evaluationPlan.reviewComplete?"Ja":"Nein"):"Nicht zwingend"}</dd></>}<dt>Referenzgedächtnis</dt><dd>{evaluationPlan.memory?.status}</dd><dt>Erwartete Modellaufrufe</dt><dd>{evaluationPlan.expectedModelCalls}</dd><dt>Erwartete Cloud-Aufrufe</dt><dd>{evaluationPlan.expectedCloudCalls}{evaluationPlan.expectedCloudCalls?" · kann Kosten verursachen":""}</dd><dt>Ground Truth / Protokoll / frühere Ergebnisse</dt><dd>Nicht enthalten</dd></dl></section>}
    <section className="variant-grid">{evaluation?.variants?.map((item:any)=><article key={item.variantId}><b>Variante {item.variantId}: {evaluationVariantLabels[item.variantId]}</b><span>{item.readiness} · {item.referenceCount||0} Referenzen</span></article>)}</section>
   </details>
  </main>}
  {tab==="analysis"&&<div className="analysis-layout unified-analysis"><aside><div className="aside-title"><span>1 · PRÜFKÖRPER AUSWÄHLEN</span><button onClick={createSpecimen}>＋</button></div><div className="batch-select-actions"><button onClick={()=>{setCheckedSpecimens(project.specimens.map(item=>item.id));setScientificPlan(undefined)}}>Alle {project.specimens.length}</button><button onClick={()=>{setCheckedSpecimens([]);setScientificPlan(undefined)}}>Keine</button></div><div className="specimens">{project.specimens.map(item=><div className={`specimen-row ${selected===item.id?"active":""}`} key={item.id}><input type="checkbox" checked={checkedSpecimens.includes(item.id)} onChange={()=>toggleSpecimen(item.id)} aria-label={`${item.id} für Analyse auswählen`}/><button onClick={()=>void load(item.id)}><b>{item.id}</b><small>{item.imageCount} Fotos · {item.analysisImageCount} analysierbar · {item.runCount||0} Läufe</small></button></div>)}</div></aside><section className="workspace">
   <section className="unified-analysis-control"><div className="analysis-step"><span>3 · KI-MODELL</span><select value={evaluationModel} onChange={event=>{setEvaluationModel(event.target.value as ModelKey);setScientificPlan(undefined)}}>{(Object.keys(modelChoices) as ModelKey[]).map(key=><option value={key} key={key}>{modelChoices[key].label}</option>)}</select><small>{modelChoices[evaluationModel].cloud?"Cloud-Modell · vor dem Start ist eine Kostenfreigabe erforderlich":"Lokale Verarbeitung über Ollama"}</small></div><div className="analysis-step"><span>4 · KLASSIFIKATIONSVARIANTE</span><select value={evaluationVariant} onChange={event=>{setEvaluationVariant(event.target.value);setScientificPlan(undefined)}}>{["1","2","2a","3"].map(id=><option value={id} key={id}>Variante {id} · {evaluationVariantLabels[id]}</option>)}</select><small>{selectedEvaluationVariant?.ready?"BEREIT":evaluation?"NICHT BEREIT":"Status wird geladen …"}</small></div><div className="analysis-start-actions"><button onClick={planScientificSeries} disabled={!checkedSpecimens.length||scientificRun?.status==="running"}>5 · Plan prüfen</button><button className="primary" onClick={startScientificSeries} disabled={!scientificPlan?.readyToStart||scientificRun?.status==="running"}>6 · Analyse starten</button></div></section>
   <div className="variant-banner"><b>Wissenschaftlicher Analyseweg</b><span>{checkedSpecimens.length} von {project.specimens.length} vorhandenen Prüfkörpern ausgewählt · Regelwerk v1.4 · zwölf gleichberechtigte Merkmale · Ground Truth wird nicht an das Modell übergeben.</span></div>
   {scientificPlan&&<section className={`scientific-plan-summary ${scientificPlan.readyToStart?"ready":"not-ready"}`}><header><div><span>GEPRÜFTER PLAN</span><h3>{scientificPlan.specimenCount} Prüfkörper · {scientificPlan.selectedImageCount} bestätigte Bilder</h3></div><b>{scientificPlan.readyToStart?"BEREIT":"NICHT BEREIT"}</b></header><dl><dt>KI-Modell</dt><dd>{modelChoices[evaluationModel].label}</dd><dt>Variante</dt><dd>Variante {scientificPlan.variant} · {evaluationVariantLabels[scientificPlan.variant]} · {scientificPlan.variantReadiness}</dd><dt>Regelwerk / Prompt</dt><dd>v{scientificPlan.classificationRulesVersion} · {scientificPlan.promptVersion}</dd><dt>Testreihe</dt><dd>{scientificPlan.testSeries?.name} {scientificPlan.seriesCreatedAutomatically?"· automatisch neu angelegt":"· wiederverwendet"}</dd><dt>Modellanfragen</dt><dd>{scientificPlan.estimatedPartialRequestCount}{scientificPlan.possibleCosts?" Cloud-Anfragen mit möglichen Kosten":" lokale Teilanfragen"}</dd><dt>Aktive Aufträge</dt><dd>{scientificPlan.activeConflicts.length||"Keine"}</dd><dt>Fehlende Bildbestätigungen</dt><dd>{scientificPlan.missingConfirmations.length||"Keine"}</dd></dl>{scientificPlan.missingConfirmations.length>0&&<ul className="variant-errors">{scientificPlan.missingConfirmations.map((item:any)=><li key={item.specimen}><b>{item.specimen}:</b> {item.error}</li>)}</ul>}{scientificPlan.activeConflicts.length>0&&<ul className="variant-errors">{scientificPlan.activeConflicts.map((item:any)=><li key={item.jobId}>{item.specimen}: {statusLabels[item.status]||item.status} · {item.model}</li>)}</ul>}{scientificPlan.variantErrors.length>0&&<ul className="variant-errors">{scientificPlan.variantErrors.map((text:string)=><li key={text}>{text}</li>)}</ul>}<details><summary>Fixierte Bildauswahl je Prüfkörper</summary><div className="scientific-selection-list">{scientificPlan.specimens.map((item:any)=><div key={item.specimen}><b>{item.specimen}</b><span>{item.selectedImageCount} Bilder</span><small>{item.images.map((image:any)=>image.filename).join(", ")||item.selectionError}</small></div>)}</div></details></section>}
   {scientificRun&&<section className="scientific-series-card current-run"><header><div><span>ANALYSEAUFTRAG</span><h3>{scientificRun.jobCount} Prüfkörper · Variante {scientificRun.evaluationVariant} · {scientificRun.model}</h3></div><b>{statusLabels[scientificRun.status]||scientificRun.status}</b></header><progress max={scientificRun.jobCount} value={scientificRun.jobs.filter((item:any)=>["succeeded","partially_succeeded","failed","cancelled"].includes(item.status)).length}/><div className="evaluation-actions"><button onClick={loadScientificRuns}>Status aktualisieren</button><button disabled={!scientificRun||!["interrupted","paused","completed_with_errors"].includes(scientificRun.status)} onClick={resumeScientificSeries}>Ausstehende/fehlgeschlagene fortsetzen</button><button disabled={scientificRun.status!=="running"} onClick={cancelScientificSeries}>Kontrolliert abbrechen</button><button disabled={scientificRun.status==="running"} onClick={exportScientificSeries}>CSV exportieren</button></div><div className="scientific-selection-list">{scientificRun.jobs.map((item:any)=><div key={item.jobId}><b>{item.specimen}</b><span>{statusLabels[item.status]||item.status}</span><small>{item.statusText||item.error||`${item.selectedImageCount??0} Bilder · ${item.partialRequestCount??1} Teilanfragen · Zusammenführung: ${item.mergeStatus||"ausstehend"}`}</small></div>)}</div></section>}
   {!detail?<div className="empty"><h2>2 · Bilder auswählen</h2><p>Öffnen Sie links einen Prüfkörper, kontrollieren Sie seine Fotos und bestätigen Sie die Auswahl.</p></div>:<><div className="toolbar"><div><h2>2 · Bilder für {detail.specimen}</h2><p><b>{detail.images.filter(item=>item.analysisSelected).length} Analysebilder ausgewählt</b> · {detail.images.filter(item=>item.isIdentification).length} Identifikationsfotos werden nie übergeben</p></div><button onClick={()=>setAllImages(true)}>Alle Bruchbilder auswählen</button><button onClick={()=>setAllImages(false)}>Alle abwählen</button><button className="primary" onClick={confirmCurrentSelection}>Auswahl bestätigen</button><button onClick={importImages}>Bilder hinzufügen</button></div><div className="gallery">{detail.images.map((image,index)=><article className={`image-tile ${image.isIdentification?"identification-image":image.analysisSelected?"analysis-image":"excluded-image"}`} onClick={()=>toggleImage(image)} key={image.name}><button className="image-preview" aria-label={`${image.name} ${image.analysisSelected?"abwählen":"auswählen"}`} onClick={event=>{event.stopPropagation();if(image.analysisEligible)toggleImage(image);else setLightbox(index)}}><img src={image.src}/></button><div className="image-tile-meta"><label onClick={event=>event.stopPropagation()}><input type="checkbox" disabled={!image.analysisEligible} checked={image.analysisSelected} onChange={()=>toggleImage(image)}/><b>{image.isIdentification?"IDENTIFIKATION · NICHT ANALYSIERT":image.analysisSelected?"ANALYSEBILD":"NICHT AUSGEWÄHLT"}</b></label><span>{image.name}</span><button className="zoom-image" onClick={event=>{event.stopPropagation();setLightbox(index)}}>Vergrößern</button></div></article>)}</div></>}
  </section></div>}
  {Boolean(false)&&<div className="analysis-layout"><aside><div className="aside-title"><span>PRÜFKÖRPER</span><button onClick={createSpecimen}>＋</button></div><div className="batch-select-actions"><button onClick={()=>setCheckedSpecimens(project.specimens.map(item=>item.id))}>Alle</button><button onClick={()=>setCheckedSpecimens([])}>Keine</button></div><div className="specimens">{project.specimens.map(item=><div className={`specimen-row ${selected===item.id?"active":""}`} key={item.id}><input type="checkbox" checked={checkedSpecimens.includes(item.id)} onChange={()=>toggleSpecimen(item.id)} aria-label={`${item.id} für Batch auswählen`}/><button onClick={()=>void load(item.id)}><b>{item.id}</b><small>{item.imageCount} Fotos · {item.analysisImageCount} analysierbar · {item.runCount||0} Läufe</small></button></div>)}</div></aside><section className="workspace">
   <section className="batch-toolbar"><div><b>Serienauswertung</b><small>{checkedSpecimens.length} Prüfkörper · {selectedModels.length} Modelle · {checkedSpecimens.length*selectedModels.length} Aufträge</small></div><div className="model-checks">{(Object.keys(modelChoices) as ModelKey[]).map(key=><label key={key}><input type="checkbox" checked={selectedModels.includes(key)} onChange={()=>toggleModel(key)}/>{modelChoices[key].label}{modelChoices[key].cloud&&<em>Cloud</em>}</label>)}</div><button onClick={plan}>Plan prüfen</button><button className="primary" onClick={startBatch} disabled={!checkedSpecimens.length||!selectedModels.length}>Batch starten</button></section>
   {batchPlan&&<section className="plan-card"><b>Geplanter Batch</b><span>{batchPlan.jobCount} unabhängige Analysen</span><span>{batchPlan.cloudRequestCount} Cloud-Anfragen</span><button onClick={()=>setBatchPlan(undefined)}>Schließen</button></section>}
   {!detail?<div className="empty"><h2>Prüfkörper auswählen</h2><p>Alle Fotos einschließlich Identifikationsbildern werden anschließend angezeigt.</p></div>:<><div className="toolbar"><div><h2>{detail.specimen}</h2><p><b>{detail.images.filter(item=>item.analysisSelected).length} von {detail.images.length} Bildern für die Analyse ausgewählt</b> · {detail.images.filter(item=>item.isIdentification).length} Identifikationsfotos</p></div><button onClick={()=>setAllImages(true)}>Alle Bruchbilder auswählen</button><button onClick={()=>setAllImages(false)}>Alle abwählen</button><button onClick={confirmCurrentSelection}>Auswahl bestätigen</button><button onClick={importImages}>Bilder hinzufügen</button><select value={singleModel} onChange={event=>setSingleModel(event.target.value as ModelKey)}>{(Object.keys(modelChoices) as ModelKey[]).map(key=><option value={key} key={key}>{modelChoices[key].label}</option>)}</select><button className="primary" disabled={!detail.images.some(item=>item.analysisSelected)||job?.state==="running"} onClick={startSingle}>Bildanalyse starten</button></div>
    <div className="variant-banner"><b>Analysemodus</b><span>{boot.evaluation?.ready?`${classes.length} gleichwertige Versagensmerkmale sind aktiv; Variante 1 bleibt referenzfrei.`:"Variante 1 bleibt gesperrt, bis die aktiven Merkmale in klassifikationsregeln.json dokumentiert sind."}</span></div>
    <div className="gallery">{detail.images.map((image,index)=><article className={`image-tile ${image.isIdentification?"identification-image":image.analysisSelected?"analysis-image":"excluded-image"}`} onClick={()=>toggleImage(image)} key={image.name}><button className="image-preview" aria-label={`${image.name} ${image.analysisSelected?"abwählen":"auswählen"}`} onClick={event=>{event.stopPropagation();if(image.analysisEligible)toggleImage(image);else setLightbox(index)}}><img src={image.src}/></button><div className="image-tile-meta"><label onClick={event=>event.stopPropagation()}><input type="checkbox" disabled={!image.analysisEligible} checked={image.analysisSelected} onChange={()=>toggleImage(image)}/><b>{image.isIdentification?"IDENTIFIKATION · NICHT ANALYSIERT":image.analysisSelected?"ANALYSEBILD":"NICHT AUSGEWÄHLT"}</b></label><span>{image.name}</span><button className="zoom-image" onClick={event=>{event.stopPropagation();setLightbox(index)}}>Vergrößern</button></div></article>)}</div>
    <section className="history-card"><div className="section-head"><div><h2>Analysehistorie</h2><p>Modell, Datum und erkannte Klassen.</p></div><select value={historyScope} onChange={event=>setHistoryScope(event.target.value as typeof historyScope)}><option value="all">Alle</option><option value="active">Aktive wissenschaftliche Testreihe</option><option value="historical">Entwicklungstests</option><option value="hidden">Ausgeblendete Ergebnisse</option></select><button onClick={resetTestHistory}>Testhistorie zurücksetzen</button><button className="danger" disabled={!detail.history.length} onClick={deleteAllSpecimenRuns}>Alle Testläufe löschen</button></div>{!filteredHistory.length?<div className="empty-result">Keine Analyseläufe in diesem Filter.</div>:<div className="history-list">{[...filteredHistory].reverse().map(run=><div className={`history-entry ${compareRunIds.includes(run.runId)?"selected":""} ${run.hidden?"hidden-run":""}`} key={run.runId}><input type="checkbox" disabled={run.hidden} checked={compareRunIds.includes(run.runId)} onChange={()=>void toggleCompare(run.runId)}/><span><b>{run.model}</b><small>{dateLabel(run.createdAt)}</small></span><em>{run.detectedCodes?.join(", ")||run.status}</em>{runMenu(run)}</div>)}</div>}</section>
    <section className="comparison-grid">{compareResults.map(item=><RunCard item={item} classes={classes} draft={assessmentDrafts[item.runId]} onDraft={patch=>updateAssessment(item.runId,patch)} onSave={()=>void saveAssessment(item.runId)} key={item.runId}/>)}</section></>}
  </section></div>}
  {tab==="results"&&<main className="tab-page"><div className="page-title"><div><h2>Ergebnisse</h2><p>{seriesInfo.active?`Aktuelle wissenschaftliche Testreihe: ${seriesInfo.active.name}`:"Noch keine aktuelle v1.4-Testreihe; sie wird beim Planen automatisch angelegt."}</p></div><button onClick={loadProjectResults}>Aktualisieren</button></div><div className="series-notice">Alle zwölf Merkmale sind gleichberechtigt. Eine Hauptversagensursache wird ausschließlich in der getrennten fachlichen Bewertung manuell festgelegt.</div><div className="filters"><select value={resultScope} onChange={event=>{setResultScope(event.target.value as typeof resultScope);setResultDetail(undefined)}}><option value="all">Alle sichtbaren Läufe</option><option value="active">Aktuelle wissenschaftliche Testreihe</option><option value="historical">Historische Entwicklungstests</option><option value="hidden">Ausgeblendete Ergebnisse</option></select><select value={resultFilters.specimen} onChange={event=>setResultFilters({...resultFilters,specimen:event.target.value})}><option value="">Alle Prüfkörper</option>{project.specimens.map(item=><option key={item.id}>{item.id}</option>)}</select><select value={resultFilters.model} onChange={event=>setResultFilters({...resultFilters,model:event.target.value})}><option value="">Alle Modelle</option>{[...new Set(projectResults.map(item=>item.model))].map(model=><option key={model}>{model}</option>)}</select><select value={resultFilters.failure} onChange={event=>setResultFilters({...resultFilters,failure:event.target.value})}><option value="">Alle Merkmale</option>{classes.map((entry:any)=><option value={entry.code} key={entry.code}>{entry.code} · {entry.name}</option>)}</select></div>{resultTable(false)}{!filteredResults.length&&<div className="empty-result">In dieser Ergebnisgruppe sind noch keine Analysen vorhanden.</div>}{resultDetail?.ok&&<RunCard item={resultDetail} classes={classes} draft={assessmentDrafts[resultDetail.runId]} onDraft={patch=>updateAssessment(resultDetail.runId,patch)} onSave={()=>void saveAssessment(resultDetail.runId)}/>}</main>}
  {tab==="export"&&<main className="tab-page"><div className="page-title"><div><h2>Export</h2><p>Wissenschaftliche Läufe als Übersichts- und Detail-CSV exportieren; historische JSON-Exporte bleiben verfügbar.</p></div><button onClick={()=>{void loadScientificRuns();void loadExportFiles()}}>Aktualisieren</button></div><div className="export-note">Fehlgeschlagene, teilweise erfolgreiche und nicht analysierte Prüfkörper bleiben eindeutig gekennzeichnet. Exportkopien können jederzeit aus den Rohanalysen neu erzeugt werden.</div><section className="export-series"><h3>Wissenschaftlichen Analyselauf exportieren</h3>{scientificRuns.length?scientificRuns.map((run:any)=><article key={run.batchId}><div><b>{run.createdAt?dateLabel(run.createdAt):run.batchId}</b><span>{run.jobCount} Prüfkörper · Variante {run.evaluationVariant} · {run.model}</span><small>{statusLabels[run.status]||run.status} · Run-ID {run.seriesRunId||run.batchId}</small></div><button disabled={run.status==="running"} onClick={()=>void exportSeries(run)}>Übersichts-CSV + Detail-CSV</button></article>):<p className="empty-result">Noch kein wissenschaftlicher Analyselauf vorhanden.</p>}</section><section className="export-files"><header><div><h3>Generierte Exportdateien</h3><p>Nur diese Kopien können gelöscht werden; Rohanalysen, Bilder, Ground Truth, Bewertungen und Testreihen bleiben geschützt.</p></div><button className="danger" disabled={!selectedExportIds.length} onClick={()=>void deleteExports(false)}>Auswahl löschen</button><button className="danger" disabled={!exportFiles.length} onClick={()=>void deleteExports(true)}>Alle Exportkopien löschen</button></header>{exportFiles.length?<div className="export-file-list">{exportFiles.map((item:any)=><label key={item.exportId}><input type="checkbox" checked={selectedExportIds.includes(item.exportId)} onChange={()=>setSelectedExportIds(current=>current.includes(item.exportId)?current.filter(id=>id!==item.exportId):[...current,item.exportId])}/><span><b>{item.name}</b><small>{item.seriesRunId?`Lauf ${item.seriesRunId}`:"Projekt-Export"} · {Math.max(1,Math.round(item.sizeBytes/1024))} KB · {dateLabel(item.modifiedAt)}</small></span></label>)}</div>:<p className="empty-result">Keine generierten Exportkopien vorhanden.</p>}</section><details className="legacy-export"><summary>Historische Einzel- und JSON-Exporte</summary><div className="page-title"><p>Vorhandene ältere Analyseläufe bleiben lesbar und exportierbar.</p><button className="primary" disabled={!exportRunIds.length} onClick={exportSelected}>{exportRunIds.length} ausgewählte Läufe exportieren</button></div>{resultTable(true,fieldFilteredResults)}</details></main>}
  <footer><span>{status||"Bereit"}</span><span>12 gleichwertige Referenzmerkmale · unveränderte KI-Originale</span></footer>
  {job?.state==="running"&&<div className="overlay"><div><div className="spinner"/><h2>{job.status||"Analyse läuft"}</h2><p>Vergangene Laufzeit: {elapsedLabel(job.startedAt,undefined,elapsedNow)}</p></div></div>}
  {error&&<div className="toast"><button onClick={()=>setError("")}>×</button><b>Hinweis</b><p>{error}</p></div>}
  {detail&&lightboxIndex>=0&&<div className="lightbox" onClick={()=>setLightbox(-1)}><button onClick={event=>{event.stopPropagation();setLightbox((lightboxIndex-1+detail.images.length)%detail.images.length)}}>‹</button><div><img src={detail.images[lightboxIndex].src}/><p>{detail.images[lightboxIndex].name}</p></div><button onClick={event=>{event.stopPropagation();setLightbox((lightboxIndex+1)%detail.images.length)}}>›</button></div>}
  {referencePreview&&<div className="lightbox reference-lightbox" onClick={()=>setReferencePreview(undefined)}><div><img src={referencePreview.src}/><p>{referencePreview.name} · {referencePreview.code}</p></div></div>}
 </div>;
}
